:root {
  color-scheme: light;
  --ink: #202b3a;
  --muted: #647183;
  --paper: #fffdf7;
  --blue: #3c6ee8;
  --yellow: #f6ca53;
  --line: #dce2e9;
}

* { box-sizing: border-box; }

body {
  min-height: 100vh;
  margin: 0;
  padding: 32px 18px;
  display: grid;
  place-items: center;
  background-color: #eaf0fb;
  background-image: linear-gradient(rgba(60, 110, 232, .07) 1px, transparent 1px), linear-gradient(90deg, rgba(60, 110, 232, .07) 1px, transparent 1px);
  background-size: 24px 24px;
  color: var(--ink);
  font: 16px/1.5 system-ui, sans-serif;
}

.card {
  width: min(100%, 500px);
  padding: 36px;
  border: 3px solid var(--ink);
  border-radius: 8px;
  background: var(--paper);
  box-shadow: 8px 8px 0 var(--ink);
}

.pixel-mark {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  border: 2px solid var(--ink);
  background: var(--yellow);
  font-size: 28px;
}

.eyebrow, .result-label {
  margin: 22px 0 6px;
  color: var(--blue);
  font-size: 14px;
  font-weight: 800;
  letter-spacing: .12em;
}

h1 { margin: 0; font-size: clamp(34px, 9vw, 48px); line-height: 1.05; letter-spacing: -.04em; }
.intro { margin: 14px 0 28px; color: var(--muted); }
.date-fields { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
label { display: grid; gap: 8px; font-weight: 700; }
input {
  min-width: 0;
  width: 100%;
  min-height: 50px;
  padding: 10px;
  border: 2px solid var(--line);
  border-radius: 4px;
  background: white;
  color: var(--ink);
  font: inherit;
}
input:hover { border-color: var(--blue); }
input:focus-visible, button:focus-visible { outline: 3px solid var(--yellow); outline-offset: 3px; }
button {
  width: 100%;
  min-height: 52px;
  margin-top: 20px;
  padding: 12px 18px;
  border: 2px solid var(--ink);
  border-radius: 4px;
  background: var(--blue);
  color: white;
  cursor: pointer;
  font: inherit;
  font-weight: 800;
  text-align: left;
  transition: transform .12s, box-shadow .12s, background .12s;
}
button span { float: right; font-size: 20px; line-height: 1.2; }
button:hover { background: #2d5dce; box-shadow: 3px 3px 0 var(--ink); transform: translate(-2px, -2px); }
button:active { box-shadow: none; transform: translate(2px, 2px); }
.results { margin-top: 26px; padding: 20px; border: 2px dashed var(--blue); background: #f0f4ff; }
.results .result-label { margin: 0; }
.days { margin: 2px 0 14px; }
.days strong { font-size: 52px; line-height: 1.15; letter-spacing: -.05em; }
.days span { color: var(--muted); font-weight: 700; }
.result-details { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; padding-top: 12px; border-top: 1px solid #cbd7f4; }
.result-details p { display: grid; gap: 2px; margin: 0; }
.result-details span { color: var(--muted); font-size: 14px; }
.result-details strong { font-size: 18px; }
.footnote { margin: 20px 0 0; color: var(--muted); font-size: 14px; }
[hidden] { display: none !important; }

@media (max-width: 420px) {
  .card { padding: 26px 22px; }
  .date-fields { grid-template-columns: 1fr; gap: 14px; }
}

const form = document.getElementById('date-form');
const firstInput = document.getElementById('first-date');
const secondInput = document.getElementById('second-date');
const results = document.getElementById('results');

function utcDay(value) {
  const [year, month, day] = value.split('-').map(Number);
  return Date.UTC(year, month - 1, day);
}

form.addEventListener('submit', (event) => {
  event.preventDefault();
  if (!form.reportValidity()) return;

  const first = utcDay(firstInput.value);
  const second = utcDay(secondInput.value);
  const difference = Math.abs(second - first) / 86400000;
  const direction = second < first ? 'Before first' : second > first ? 'After first' : 'Same day';

  document.getElementById('day-count').textContent = difference;
  document.getElementById('week-count').textContent = Math.floor(difference / 7);
  document.getElementById('direction').textContent = direction;
  results.hidden = false;
});
